mapper.select:
select device_id, entity_id, device_code, device_name, device_type, rated_capacity_kw, auto_yx_num, energized_yx_num, status, create_by, create_time, remark
from vqms_art27_device

     and entity_id = #{entityId}
     and device_code like concat('%', #{deviceCode}, '%')
     and status = #{status}

order by device_code

mapper.update:
update vqms_art27_device
entity_id = #{entityId}, device_code = #{deviceCode}, device_name = #{deviceName}, device_type = #{deviceType}, rated_capacity_kw = #{ratedCapacityKw}, auto_yx_num = #{autoYxNum}, energized_yx_num = #{energizedYxNum}, status = #{status}, update_by = #{updateBy}, remark = #{remark},
where device_id = #{deviceId}

update vqms_art27_month
auto_hours = #{autoHours}, energized_hours = #{energizedHours}, rate_penalty_days = #{ratePenaltyDays}, nameplate_days = #{nameplateDays}, regulator_rate = #{regulatorRate}, regulator_penalty = #{regulatorPenalty}, update_by = #{updateBy}, remark = #{remark},
where id = #{id}
